def fig(f,id,height=390):
 f.update_layout(template='plotly_white',height=height,margin=dict(l=65,r=28,t=35,b=65),font=dict(family='Arial, sans-serif',color='#23334b',size=12),colorway=COLORS,legend=dict(orientation='h',y=1.15),paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(0,0,0,0)',hoverlabel=dict(bgcolor='white'))
 return f.to_html(full_html=False,include_plotlyjs=False,div_id=id,config={'responsive':True,'displaylogo':False,'modeBarButtonsToRemove':['lasso2d','select2d']})
def table(d,percent=(),digits=2):
 v=d.copy()
 for c in v:
  if c in percent:v[c]=v[c].map(lambda n:'—' if pd.isna(n) else f'{n*100:.{digits}f}%'.replace('.',','))
  elif pd.api.types.is_float_dtype(v[c]):v[c]=v[c].map(lambda n:'—' if pd.isna(n) else f'{n:,.{digits}f}'.replace(',','X').replace('.',',').replace('X','.'))
 return '<div class="table-wrap">'+v.to_html(index=False,border=0,escape=True,classes='data-table')+'</div>'
def box(title,body,kind='insight'):return f'<aside class="callout {kind}"><strong>{title}</strong><div>{body}</div></aside>'
def io(inp,process,out):return f'<div class="io"><div><small>INPUT · ENTRADA</small>{inp}</div><div><small>PROCESSO · O QUE FIZ</small>{process}</div><div><small>OUTPUT · SAÍDA</small>{out}</div></div>'
def code(s):return '<details class="code"><summary>Ver a lógica em Python</summary><pre><code>'+html.escape(s.strip())+'</code></pre></details>'
